import {characterArt} from './haunt-art.js';
const $=s=>document.querySelector(s),API='/api/memory-glitch',LEVELS=[100,50,0],BATCH_KEY='memory-glitch-latest-test-batch';
const CATS=[{url:'./assets/cat-chaos.jpg',alt:'An orange cat making an unhinged face'},{url:'./assets/cat-calico.jpg',alt:'A calico cat wearing glasses and buck teeth'},{url:'./assets/cat-polite.jpg',alt:'An awkwardly polite smiling cat'},{url:'./assets/cat-dinner.jpg',alt:'Woman yelling beside a confused cat at a dinner table'},{url:'./assets/cat-grumpy.jpg',alt:'A grumpy-looking cat'},{url:'./assets/cat-crying.png',alt:'A cat with edited teary eyes'},{url:'./assets/cat-confused.jpg',alt:'A confused-looking cat'},{url:'./assets/cat-surprised.jpg',alt:'A surprised-looking cat'},{url:'./assets/trump-meme-1.gif',alt:'Animated Trump caricature dancing',source:'https://tenor.com/view/trump-dancing-dance-move-gif-16005737'},{url:'./assets/trump-meme-2.gif',alt:'Donald Trump winking with an existing humorous caption',source:'https://tenor.com/view/donald-trump-wink-president-usa-gif-2973401692064150166'},{url:'./assets/trump-meme-3.gif',alt:'Donald Trump pointing and giving a thumbs up with an existing I see what you did there caption',source:'https://tenor.com/view/i-see-you-i-see-what-you-did-there-trump-wink-thumbs-up-gif-11497468735575552050'},{url:'./assets/trump-meme-4.gif',alt:'Donald Trump laughing at a podium',source:'https://tenor.com/pt-BR/view/trump-laughing-gif-6044302'},{url:'./assets/trump-meme-5.gif',alt:'Donald Trump making a wrong reaction at a debate microphone',source:'https://tenor.com/view/wrong-drumpf-trump-stupid-gif-6220235'}];
let state={revision:0,experiments:[]},configured=false,model='',running=false,stopRequested=false,batchId='',startedAt='',completedAt='',results=new Map(),failures=new Map(),activeLevel=null;
const el=(tag,className,text)=>{const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n};
const picture=(cat,className='')=>{const img=el('img',className);img.src=cat.url;img.alt=cat.alt;img.decoding='async';return img};
const readableError=error=>{const text=String(error?.message||'The request failed.');return /[\u4e00-\u9fff]/.test(text)?'The backend could not complete this level. Saved results remain available. Please run a fresh test.':text};
async function request(body){const response=await fetch(API,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify({revision:state.revision,...body}):undefined});let payload;try{payload=await response.json()}catch{throw new Error('The server returned an unreadable response. Your completed levels are still saved.')}if(payload.state)state=payload.state;if(typeof payload.configured==='boolean')configured=payload.configured;if(payload.model)model=payload.model;if(!response.ok){if(response.status===409)throw new Error('Another tab updated the lab session. This level did not complete; the latest state has been loaded.');throw new Error(payload.error||`Request failed (${response.status}).`)}return payload}
function syncResults(){for(const result of state.experiments||[])if(result.batchId===batchId&&LEVELS.includes(result.level)&&result.repeat===1)results.set(result.level,result)}
function controls(){const run=$('#test-run');run.disabled=running||!configured;run.textContent=results.size||failures.size?'Run a fresh test ↗':'Run real forgetting test ↗';$('#test-stop').hidden=!running;$('#test-stop').disabled=stopRequested;$('#test-stop').textContent=stopRequested?'Stopping after this call…':'Stop after this call';$('#test-export').disabled=!results.size&&!failures.size;$('#test-model').textContent=`Model: ${model||'connecting'} · Temperature: 0`;$('#test-progress-bar').value=results.size+failures.size}
function metric(label,value,kind=''){const n=el('div',`test-metric ${kind}`);n.append(el('strong','',String(value)),el('span','',label));return n}
function factsTable(result){const wrap=el('div','test-table-scroll'),table=el('table','test-facts-table'),head=el('thead'),tr=el('tr');for(const value of ['Question','Reference answer','Model answer','In input?','Result'])tr.append(el('th','',value));head.append(tr);const body=el('tbody');for(const row of result.rows||[]){const line=el('tr',`row-${row.status||'unknown'}`);line.append(el('td','',row.question||''),el('td','',row.expected??''),el('td','',row.value===null||row.value===undefined?'Unknown':String(row.value)),el('td','',row.inContext?'Yes':'No'),el('td','',row.status||'unknown'));body.append(line)}table.append(head,body);wrap.append(table);return wrap}
function reaction(result){const missed=result.tested-result.correct;if(missed<=0)return null;const hash=[...String(result.id||result.level)].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,0),cat=CATS[hash%CATS.length];const wrap=el('div','test-reaction');const frame=el('figure','test-cat-meme');const line=result.mismatch>0?'CONFIDENCE: YUGE. CORRECTNESS: PLEASE HOLD.':result.level===0?'NO FACTS. JUST VIBES.':'THE FACTS LEFT. I DID TOO.';frame.append(el('figcaption','',line),picture(cat));wrap.append(el('span','test-reaction-tag','CONTROLLED RECALL MISS'),frame,el('p','',result.mismatch>0?`${result.mismatch} different answers need review. See the reference and model output below.`:`${result.unknown} answers were unknown. Withholding their source can cause this; the meme is only a reaction.`));const source=el('a','reaction-credit','Fictional reaction · Image source ↗');source.href=cat.source||'./assets/cat-sources.json';source.target='_blank';source.rel='noopener noreferrer';wrap.append(source);return wrap}
function render(){const area=$('#test-results');area.replaceChildren();for(const level of LEVELS){const result=results.get(level),error=failures.get(level),active=level===activeLevel;const card=el('article',`test-level ${result?'complete':error?'failed':active?'running':'waiting'}`);card.dataset.level=String(level);const header=el('div','test-level-heading');header.append(el('h2','',`${level}% INPUT`),el('span','',result?'MEASURED':error?'FAILED':active?'LIVE CALL':'WAITING'));card.append(header,el('p','test-retention',result?`${result.retained} of ${result.total??20} facts actually sent`:`${level/5} of 20 facts will be sent`));if(result){const stats=el('div','test-metrics');stats.append(metric('Correct',result.correct,'correct'),metric('Unknown',result.unknown,'unknown'),metric('Mismatch',result.mismatch,'mismatch'));const bar=el('div','test-score');const fill=el('i');fill.style.width=`${Math.max(0,Math.min(100,result.score??0))}%`;bar.append(fill);card.append(stats,bar,el('p','test-score-label',`${result.score??0}% recall · ${result.correct}/${result.tested} tested facts`));const react=reaction(result);if(react)card.append(react);else card.append(el('p','test-all-correct','All tested facts recalled correctly. No meme rain.'));const facts=el('details','test-evidence');facts.append(el('summary','',`Inspect all ${result.tested} answers`),factsTable(result));const audit=el('details','test-evidence');audit.append(el('summary','','See actual model input + receipt'),el('pre','',JSON.stringify({runId:result.id,batchId:result.batchId,model:result.model,temperature:result.audit?.temperature,retained:result.retained,total:result.total,audit:result.audit},null,2)));card.append(facts,audit)}else if(error)card.append(el('p','test-level-error',error),el('p','test-level-note','This level has no score. Completed levels remain available.'));else card.append(el('p','test-level-note',active?'The real model is answering 20 questions. Waiting for the server result…':'A fresh test will run this level once. No result has been generated.'));area.append(card)}controls()}
function burst(level){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layer=$('#haunt-effects');if(layer.childElementCount)return;for(let i=0;i<3;i++){const p=el('span','haunt-particle cat-particle');p.style.left=`${10+i*29}%`;p.style.animationDelay=`${i*.15}s`;p.append(picture(CATS[(i+Math.max(0,LEVELS.indexOf(level))*3)%CATS.length]));layer.append(p);p.addEventListener('animationend',()=>p.remove(),{once:true});setTimeout(()=>p.remove(),4000)}for(const[type,i]of[['candy',0],['spider',1],['ghost',2]]){const p=el('span',`haunt-particle ${type}`);p.style.left=`${20+i*30}%`;p.style.animationDelay=`${i*.13}s`;p.append(characterArt(type));layer.append(p);p.addEventListener('animationend',()=>p.remove(),{once:true});setTimeout(()=>p.remove(),4000)}}
async function load(){try{await request();try{batchId=localStorage.getItem(BATCH_KEY)||''}catch{}if(batchId)syncResults();const connection=$('#test-connection');connection.className=`connection ${configured?'connected':'error'}`;connection.replaceChildren(el('i'),document.createTextNode(configured?'Netlify connected':'AI not configured'));$('#test-progress').textContent=results.size?`Restored ${results.size} measured levels from your most recent test. Run fresh to make new model calls.`:configured?'Ready. Click Run real forgetting test to make three live model calls.':'Netlify AI Gateway is not configured yet.';render()}catch(error){$('#test-connection').className='connection error';$('#test-connection').textContent='Connection unavailable';$('#test-progress').textContent=readableError(error);render()}}
async function run(){if(running||!configured)return;running=true;stopRequested=false;batchId=crypto.randomUUID();startedAt=new Date().toISOString();completedAt='';results=new Map();failures=new Map();try{localStorage.setItem(BATCH_KEY,batchId)}catch{}render();for(const[levelIndex,level]of LEVELS.entries()){if(stopRequested)break;activeLevel=level;$('#test-progress').textContent=`Live call ${levelIndex+1}/3: retaining ${level/5} facts and testing 20 answers…`;render();try{const payload=await request({operation:'experiment',level,repeat:1,batchId,locale:'en'});const result=payload.experiment;if(!result||result.batchId!==batchId||result.level!==level||!Array.isArray(result.rows))throw new Error('The server returned an incomplete test result. This level has not been scored.');results.set(level,result);model=result.model||model;render();if(result.correct<result.tested)burst(level)}catch(error){failures.set(level,readableError(error));try{await request();syncResults();if(results.has(level))failures.delete(level)}catch{}render()}}activeLevel=null;running=false;completedAt=new Date().toISOString();const finished=results.size+failures.size;$('#test-progress').textContent=stopRequested&&finished<3?`Stopped after the current call. ${results.size} measured levels saved; ${3-finished} not run.`:failures.size?`Finished with ${results.size} measured levels and ${failures.size} failed calls. Failed levels are not scored.`:`All three live tests complete. ${results.size*20} answers measured. Open any level's evidence below.`;render()}
function exportResults(){const data={schema:1,product:'Memory Glitch real forgetting test',batchId,startedAt,completedAt,model,temperature:0,levelsRequested:LEVELS,note:'Controlled recall on 20 synthetic facts per level. Fields are actually withheld from model input. Correct uses normalized exact matching; unknown is abstention, mismatch needs review. Scores do not measure memory capacity. Image memes are fictional reactions.',results:LEVELS.filter(l=>results.has(l)).map(l=>results.get(l)),failures:[...failures].map(([level,error])=>({level,error}))};const serialized=JSON.stringify(data,null,2);$('#test-export-json').value=serialized;$('#test-export-preview').hidden=false;$('#test-export-preview').open=true;const url=URL.createObjectURL(new Blob([serialized],{type:'application/json'}));const a=el('a');a.href=url;a.download=`memory-glitch-test-${batchId.slice(0,8)||'results'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
$('#test-run').addEventListener('click',run);$('#test-stop').addEventListener('click',()=>{stopRequested=true;$('#test-progress').textContent='Stop requested. Waiting for the current server call to finish; no further level will start.';controls()});$('#test-export').addEventListener('click',exportResults);$('#test-select-export').addEventListener('click',()=>{$('#test-export-json').focus();$('#test-export-json').select()});render();load();
